#!/usr/bin/env bash
# W1 final: 1-SE calibration rule in both policies + stats (stabilises NTC-full).
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing 1-SE calibrated scripts..."
decode "scripts/ntc_w1_stats.py" << 'B64EOF'

B64EOF
decode "scripts/ntc_w1_policies.py" << 'B64EOF'

B64EOF
echo ""
echo "Installed. Re-run stats for all three (instant):"
echo "  python scripts/ntc_w1_stats.py --probes experiments/ntc/w1_math500_Qwen3-4B.json"
echo "  python scripts/ntc_w1_stats.py --probes experiments/ntc/w1_gsm8k_Qwen3-4B.json"
echo "  python scripts/ntc_w1_stats.py --probes experiments/ntc/w1_gpqa16k_Qwen3-4B.json"